namespace LWS.TruckSports {
public sealed class SportsUpdateSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();readonly Dictionary<string,string> savedPrefs=new Dictionary<string,string>();readonly List<Gamepad> pads=new List<Gamepad>();Keyboard keyboard;Mouse mouse;InputSettings original,probe;string folder,flag;bool finished,error;BilliardsMatch bill;BilliardsSession session;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){var args=Environment.GetCommandLineArgs();foreach(var key in new[]{"-tsBilliardsUpdate","-tsBilliardsAI","-tsBilliardsGroup"})if(Array.IndexOf(args,key)>=0){var g=new GameObject("Truck Sports update validation");DontDestroyOnLoad(g);g.AddComponent<SportsUpdateSmoke>().flag=key;return;}}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("UpdateSmokeTest");Directory.CreateDirectory(folder);foreach(var key in new[]{"TruckBilliards.Setup.v2","TruckHockey.Setup.v2"})savedPrefs[key]=LWS.TruckSports.SportsPrefs.HasKey(key)?LWS.TruckSports.SportsPrefs.GetString(key):null;original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Sports update probe keyboard");Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;records.Add("RUNTIME ERROR "+message);}}
 void Update(){if(finished)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator nested){steps.Push(nested);continue;}return;}Finish(error?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError("TS_UPDATE_FAIL "+e);Finish(2);}}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Wait(Func<bool> test,float seconds,string name){float end=Time.realtimeSinceStartup+seconds;while(!test()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout: "+name+" "+State());yield return null;}}
 string State(){if(bill==null)return "";int owner=bill.rules.Turn;var ai=session.agents[owner];return "phase="+bill.rules.Phase+" turn="+owner+" shots="+bill.strikeCount+" cue="+bill.balls[0].body.position+" truck="+ai.truck.transform.position+" speed="+ai.truck.Speed+" stage="+ai.ExecutionState+" attempts="+ai.RecoveryAttempts+" armed="+ai.truck.Armed;}
 void Check(bool test,string description){if(!test)throw new Exception(description+" "+State());records.Add("PASS "+description);Debug.Log("TS_UPDATE_PASS "+description);}
 void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}
 void Finish(int code){finished=true;foreach(var p in savedPrefs)if(p.Value==null)LWS.TruckSports.SportsPrefs.DeleteKey(p.Key);else LWS.TruckSports.SportsPrefs.SetString(p.Key,p.Value);LWS.TruckSports.SportsPrefs.Save();File.WriteAllLines(Path.Combine(folder,"results.txt"),records);foreach(var pad in pads)if(pad.added)InputSystem.RemoveDevice(pad);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(mouse!=null&&mouse.added)InputSystem.RemoveDevice(mouse);InputSystem.settings=original;Destroy(probe);Time.timeScale=1;Debug.Log("TS_UPDATE_FINISHED code="+code);Application.Quit(code);}
 void OnDestroy(){Application.logMessageReceived-=Log;}
 void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 void StartBill(BilliardsMode mode,int breaker=0){Keys();session.SelectMode(mode);session.breakChoice=breaker;session.format=BilliardsFormat.SingleRack;session.difficulty=BilliardsDifficulty.Hard;session.players[0].difficulty=BilliardsDifficulty.Hard;session.players[1].difficulty=BilliardsDifficulty.Hard;Check(session.StartMatch(),"start "+mode);}
 void Layout(Vector3 cue,Vector3 eight,bool target=false){foreach(var b in bill.balls)if(b.number!=0&&b.number!=8&&(!target||b.number!=1))b.SetPocketed(true);bill.balls[0].Restore(cue);bill.balls[8].Restore(eight);session.ResetAIPlans();Physics.SyncTransforms();}
 IEnumerator ControllerGroup(){
 for(int i=0;i<2;i++)pads.Add(InputSystem.AddDevice<Gamepad>("Billiards group owner "+i));foreach(var p in pads)InputSystem.QueueStateEvent(p,new GamepadState());session.SelectMode(BilliardsMode.SeparateControllers);session.Assign(0,pads[0]);session.Assign(1,pads[1]);session.breakChoice=0;session.StartMatch();bill.rules.BeginShot();bill.rules.Contact(1);bill.rules.Pocket(1,1);bill.rules.Pocket(9,2);bill.rules.Resolve();session.ShotResolved(0);yield return Delay(.2f);InputSystem.QueueStateEvent(pads[1],new GamepadState().WithButton(GamepadButton.South));yield return Delay(.15f);session.menus.Action("solids");Check(bill.rules.Phase==MatchPhase.GroupSelection,"opponent controller cannot submit group choice");InputSystem.QueueStateEvent(pads[1],new GamepadState());InputSystem.RemoveDevice(pads[0]);yield return Delay(.1f);Check(session.Screen==BilliardsScreen.Disconnect&&bill.rules.Phase==MatchPhase.GroupSelection,"group choice survives assigned controller disconnect");InputSystem.AddDevice(pads[0]);InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.South));yield return Delay(.1f);session.Resume();yield return Delay(.15f);Check(bill.rules.Phase==MatchPhase.GroupSelection&&session.Screen==BilliardsScreen.GroupSelection&&session.players[0].pad==pads[0],"held group confirmation consumed after reconnect without changing ownership");InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return Delay(.15f);InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.South));yield return Delay(.15f);session.menus.Action("solids");Check(bill.rules.PlayerGroup==1&&bill.rules.Turn==0,"fresh owning controller chooses group");InputSystem.QueueStateEvent(pads[0],new GamepadState());
 mouse=InputSystem.AddDevice<Mouse>("Billiards group pointer");yield return Delay(.15f);session.StartMatch();MixedGroup();yield return Delay(.2f);var choice=GroupPoint();Pointer(choice,false);yield return Delay(.1f);Pointer(choice,true);yield return Delay(.1f);Pointer(choice,false);yield return Delay(.15f);Check(bill.rules.PlayerGroup==2&&session.Screen==BilliardsScreen.Match&&bill.strikeCount==0,"controller-owned shooter can choose stripes through actual mouse UI without firing a shot");
 Pointer(choice,true);yield return Delay(.1f);session.StartMatch();MixedGroup();yield return Delay(.15f);Pointer(choice,false);yield return null;session.menus.Action("stripes");Check(bill.rules.Phase==MatchPhase.GroupSelection,"mouse press held across group transition is consumed");yield return Delay(.15f);Pointer(choice,true);yield return Delay(.1f);Pointer(choice,false);yield return Delay(.15f);Check(bill.rules.PlayerGroup==2&&session.Screen==BilliardsScreen.Match,"fresh mouse click succeeds after consumed held press");
 }
 void MixedGroup(){bill.rules.BeginShot();bill.rules.Contact(1);bill.rules.Pocket(1,1);bill.rules.Pocket(9,2);bill.rules.Resolve();session.ShotResolved(0);}
 Vector2 GroupPoint(){foreach(var action in session.menus.pages[(int)BilliardsScreen.GroupSelection].GetComponentsInChildren<BilliardsMenuAction>())if(action.action=="stripes")return RectTransformUtility.WorldToScreenPoint(null,action.transform.position);throw new Exception("Missing group mouse target");}
 void Pointer(Vector2 position,bool pressed){var state=new MouseState{position=position};if(pressed)state=state.WithButton(MouseButton.Left);InputSystem.QueueStateEvent(mouse,state);}
 IEnumerator Run(){yield return Delay(.4f);SportsNavigation.LoadSport(SportsNavigation.Billiards);yield return Delay(.5f);bill=FindAnyObjectByType<BilliardsMatch>();session=bill.session;Capture("01-setup");yield return Delay(.1f);if(flag=="-tsBilliardsGroup"){yield return ControllerGroup();yield break;}if(flag=="-tsBilliardsAI"){yield return Autonomous();yield break;}
 StartBill(BilliardsMode.SharedKeyboard);yield return Delay(1);Keys(Key.W);yield return Delay(.35f);Check(bill.player.Speed>1&&session.players[0].released,"held human throttle drives");session.Show(BilliardsScreen.Match);yield return Delay(.15f);Check(session.players[0].released&&bill.player.Speed>1,"idempotent Match display preserves held drive");Keys();yield return Delay(.4f);
 StartBill(BilliardsMode.SharedKeyboard);Layout(new Vector3(0,.5f,-6),new Vector3(4,.5f,8),true);bill.balls[1].Restore(new Vector3(0,.5f,-3));yield return Delay(1);Keys(Key.W);yield return Wait(()=>bill.strikeCount==1,5,"actual human break");Check(bill.LastStrikeOpening&&bill.LastStrikeSpeed>bill.player.maxShotSpeed,"opening boost applies on actual bumper contact in initial two-ball fixture");Keys(Key.W,Key.D);yield return Wait(()=>bill.resolutionCount==1,45,"physical shot settles");Check(session.players[0].released&&bill.player.Speed>1,"held drive survives resolving and ordinary turn change");Check(bill.balls[0].body.collisionDetectionMode==CollisionDetectionMode.ContinuousDynamic,"break CCD retained");Capture("02-break");yield return Delay(.1f);Keys();
 StartBill(BilliardsMode.SinglePlayer);yield return Delay(1);bill.rules.BeginShot();bill.rules.Contact(1);bill.balls[0].Restore(new Vector3(-4.8f,.5f,0));bill.balls[0].body.linearVelocity=new Vector3(-2,0,0);yield return Wait(()=>bill.rules.Phase==MatchPhase.Placement,8,"physical scratch");yield return Wait(()=>bill.strikeCount==1,65,"AI scratch placement then physical cue strike");Check(bill.rules.ShotId==2&&bill.strikeCount==1,"scratch AI makes physical shot without navigation forfeit");
 StartBill(BilliardsMode.SinglePlayer,1);bill.rules.BeginShot();bill.rules.Contact(1);for(int i=1;i<=7;i++)bill.rules.Pocket(i,i);bill.rules.Resolve();Layout(new Vector3(5.45f,.5f,5),new Vector3(5.45f,.5f,8));yield return Wait(()=>bill.strikeCount==1,65,"near-rail eligible eight physical strike");Check(bill.strikeCount==1&&!bill.rules.Notice.StartsWith("AI forfeits"),"near-rail AI physically attempts shot");Capture("03-rail");yield return Delay(.1f);
 StartBill(BilliardsMode.SinglePlayer,1);bill.rules.BeginShot();bill.rules.Contact(1);for(int i=2;i<=7;i++)bill.rules.Pocket(i,i);bill.rules.Resolve();Layout(new Vector3(2.2f,.5f,0),new Vector3(4,.5f,8),true);bill.balls[1].Restore(new Vector3(4.6f,.5f,0));bill.ai.ResetTruck(new Vector3(-1,0,0),Quaternion.Euler(0,90,0));session.ResetAIPlans();Physics.SyncTransforms();yield return Wait(()=>bill.rules.Pocketed.Contains(1)&&bill.resolutionCount>=1,65,"AI physically pots own ball");Check(bill.rules.Turn==1,"legal physical AI pot retains shooter");yield return Wait(()=>bill.strikeCount>=2,65,"retained AI turn next physical strike");Check(!bill.LastStrikeOpening&&bill.LastStrikeSpeed<=bill.ai.maxShotSpeed+.1f,"retained turn replans and normal strike cap restored");
 StartBill(BilliardsMode.SinglePlayer);var roam=bill.ai.transform.position;yield return Delay(3);Check(Vector3.Distance(roam,bill.ai.transform.position)>.4f&&session.agents[1].Roaming&&!bill.ai.deliberate&&bill.strikeCount==0,"off-turn AI roams without interfering");
 StartBill(BilliardsMode.SharedKeyboard);bill.rules.BeginShot();bill.rules.Contact(1);bill.rules.Pocket(1,1);bill.rules.Pocket(9,2);bill.rules.Resolve();session.ShotResolved(0);Capture("04-group-choice");yield return Delay(.1f);Check(session.Screen==BilliardsScreen.GroupSelection&&bill.rules.Turn==0&&bill.rules.PlayerGroup==0,"mixed-group rule fixture opens shooter modal");Check(!session.ChooseGroup(1,1),"opponent group choice rejected");session.Pause();session.Resume();Check(session.Screen==BilliardsScreen.GroupSelection,"pause preserves pending group choice");Keys();yield return Delay(.3f);Keys(Key.G);yield return Delay(.15f);Keys();Check(bill.rules.PlayerGroup==2&&bill.rules.Turn==0&&bill.rules.Pocketed.Contains(1)&&bill.rules.Pocketed.Contains(9),"owned fresh keyboard chooses stripes with pots retained");Capture("04-group-confirmed");
 StartBill(BilliardsMode.SharedKeyboard);yield return Delay(1);Keys(Key.W);yield return Wait(()=>bill.strikeCount==1,5,"full rack physical opening break");Keys();Check(bill.LastStrikeOpening&&bill.LastStrikeSpeed>bill.player.maxShotSpeed,"full rack receives opening-only boost");yield return Wait(()=>bill.resolutionCount==1,65,"full rack settles after strong physical break");foreach(var b in bill.balls)Check(b.Pocketed||(Mathf.Abs(b.body.position.x)<=bill.halfWidth+.1f&&Mathf.Abs(b.body.position.z)<=bill.halfLength+.1f),"fast break contained / pocket registered "+b.number);Check(bill.rules.RespotEight?!bill.balls[8].Pocketed:true,"opening eight respot preserved");
 yield return ControllerGroup();
 StartBill(BilliardsMode.AIVsAI);bill.rules.BeginShot();bill.rules.Contact(1);bill.rules.Pocket(1,1);bill.rules.Pocket(9,2);bill.rules.Resolve();session.ShotResolved(0);yield return Wait(()=>bill.rules.Phase==MatchPhase.Aiming,2,"automatic AI group choice");Check(bill.rules.PlayerGroup!=0&&bill.rules.Turn==0,"AI group choice needs no human confirmation");
 session.format=BilliardsFormat.BestOf3;session.StartMatch();for(int rack=0;rack<3;rack++){int shooter=bill.rules.Turn;bill.rules.BeginShot();bill.rules.Contact(1);for(int n=1;n<=7;n++)bill.rules.Pocket(n,n);bill.rules.Resolve();session.ShotResolved(shooter);bill.rules.BeginShot();bill.rules.Contact(8);bill.rules.Pocket(8,10);bill.rules.Resolve();session.ShotResolved(shooter);if(rack<2){Check(session.Screen==BilliardsScreen.Result&&!session.series.Finished,"AI-only between-rack result readable");yield return Wait(()=>session.series.RackNumber==rack+2&&bill.rules.ShotId==0,4,"automatic AI-only next rack");}}yield return Delay(3);Check(session.Screen==BilliardsScreen.Result&&session.series.Finished,"AI-only final series result remains visible");records.Add("AI series progression test injects rule outcomes; separate autonomous rack test requires physical shots throughout.");
 StartBill(BilliardsMode.AIVsAI);session.players[0].name="Azure bot";session.players[1].name="Amber bot";session.players[0].difficulty=BilliardsDifficulty.Easy;session.players[1].difficulty=BilliardsDifficulty.Hard;session.SaveSetup();Check(session.Name(0)=="Azure bot"&&session.Name(1)=="Amber bot"&&session.DifficultyFor(0)==BilliardsDifficulty.Easy&&session.DifficultyFor(1)==BilliardsDifficulty.Hard,"named AI slots have independent difficulties");records.Add("Physical reproductions use an initial rail layout / group eligibility fixture or initial scratch velocity, then leave AI navigation and bumper contact live. Mixed-group modal is a rule/input fixture. Injected keyboard is not real hardware.");
 }
 IEnumerator Autonomous(){StartBill(BilliardsMode.AIVsAI);int last=0;float start=Time.realtimeSinceStartup;while(bill.rules.Phase!=MatchPhase.Ended){if(Time.realtimeSinceStartup-start>900)throw new Exception("Autonomous rack exceeded 15 minutes "+State());if(bill.strikeCount!=last){last=bill.strikeCount;records.Add("PHYSICAL_SHOT "+last+" elapsed="+(Time.realtimeSinceStartup-start).ToString("F1"));File.WriteAllLines(Path.Combine(folder,"progress.txt"),records);}yield return null;}Check(bill.strikeCount>1&&session.series.Finished,"complete autonomous AI versus AI rack without shot-to-shot relocation");Capture("05-autonomous-result");records.Add("Autonomous elapsed="+(Time.realtimeSinceStartup-start).ToString("F1")+" shots="+bill.strikeCount+" winner="+bill.rules.Winner);}
